#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-26 03:45 — TASK 4 sessions are written by overhead_sweep_v8.sh under
# $DEST_BASE/<family>/lttng_1/fish_<ts> (the sweep mounts that dir as /root/fish_traces), but queue4's pipelines phase and
# post_run_pipeline.sh expect ~/fish_traces/<session>. Link every TASK 4 session into ~/fish_traces (polled every 5 s until
# "TASK4 DONE") and keep a session -> family map for task4_summary.py.
set -u; LD=$HOME/fish_traces/night_20261025_final; MAP=$LD/task4_sessions_map.txt; touch "$MAP"
N0=$(grep -c "TASK4 DONE" "$LD/queue.log" 2>/dev/null || true)   # earlier (aborted) TASK 4 attempts logged it too: stop on a NEW one
while :; do
  for d in "$LD"/task4c/*/lttng_1/fish_2*; do
    [ -d "$d" ] || continue; S=$(basename "$d"); F=$(basename "$(dirname "$(dirname "$d")")")
    [ -e "$HOME/fish_traces/$S" ] || { ln -s "$d" "$HOME/fish_traces/$S" && echo "[$(date +%T)] linked $S -> $F" >> "$LD/task4_links.log"; }
    grep -q "^$S " "$MAP" || echo "$S $F" >> "$MAP"
  done
  [ "$(grep -c "TASK4 DONE" "$LD/queue.log" 2>/dev/null || true)" -gt "${N0:-0}" ] && { echo "[$(date +%T)] TASK4 DONE seen; exit" >> "$LD/task4_links.log"; break; }
  sleep 5
done
